// ============================================================================
// DISCORD REGISTRY - Build Registry with Metadata
// ============================================================================
// Discord Workflow Metadata
const discordMetadata = {
  "discord-registry": {
    "label": "Registry",
    "icon": "📋",
    "description": "Liste tous les workflows Discord disponibles",
    "tags": ["discord", "registry", "discovery"],
    "scope": "system"
  },
  "discord-get-plans": {
    "label": "Get Plans",
    "icon": "📊",
    "description": "Recupere la liste des plans disponibles pour un projet",
    "tags": ["discord", "plans", "subscription"],
    "scope": "user",
    "command": "/plans"
  },
  "discord-get-subscriber": {
    "label": "Get Subscriber",
    "icon": "👤",
    "description": "Recupere les informations d'un abonne (plan, credits)",
    "tags": ["discord", "subscriber", "credits"],
    "scope": "user",
    "command": "/plan, /credits"
  },
  "discord-get-balance": {
    "label": "Get Balance",
    "icon": "💰",
    "description": "Recupere le solde et les transactions recentes",
    "tags": ["discord", "balance", "transactions"],
    "scope": "user",
    "command": "/solde"
  },
  "discord-get-transactions": {
    "label": "Get Transactions",
    "icon": "📜",
    "description": "Recupere l'historique des transactions",
    "tags": ["discord", "transactions", "history"],
    "scope": "user",
    "command": "/account"
  }
};

const webhook = $env.N8N_BASE_URL;
const webhookBase = $env.N8N_WEBHOOK_BASE_URL;
const apiUrl = $env.API_URL;

// ============================================================================
// BUILD REGISTRY
// ============================================================================

const workflows = $input.first().json.data || [];

// Filter active Discord workflows
const discordWorkflows = workflows.filter(w => 
  w.active && 
  w.name.startsWith('DISCORD')
);

// Build tools object
const tools = {};

for (const workflow of discordWorkflows) {
  // Find all webhook nodes in the workflow
  const webhookNodes = workflow.nodes?.filter(n => n.type === 'n8n-nodes-base.webhook') || [];

  for (const webhookNode of webhookNodes) {
    const webhookPath = webhookNode.parameters?.path || webhookNode.webhookId;
    const toolName = webhookPath;

    // Get metadata
    const meta = discordMetadata[toolName] || {};

    tools[toolName] = {
      name: workflow.name,
      label: meta.label || workflow.name.replace('DISCORD - ', ''),
      icon: meta.icon || '🤖',
      description: meta.description || `Discord Tool: ${workflow.name}`,
      tags: meta.tags || ['discord'],
      scope: meta.scope || 'user',
      command: meta.command || null,
      workflow_id: workflow.id,
      endpoint: `/webhook/${webhookPath}`,
      webhook_url: `${webhookBase}/${webhookPath}`,
      method: webhookNode.parameters?.httpMethod || 'GET',
      active: workflow.active
    };
  }
}

// Build final registry response
const registry = {
  version: "1.0",
  updated_at: new Date().toISOString(),
  n8n: {
    webhook_base: webhookBase
  },
  scopes: {
    user: "Endpoint accessible par le bot Discord",
    system: "Endpoint interne pour orchestration"
  },
  total_tools: Object.keys(tools).length,
  tools: tools
};

return { json: registry };

